class Solution {
public:
    vector<string> generateParenthesis(int n) {
        vector<string> res;
        string cur;
        auto dfs = [&](auto& self, int open_c, int close_c) -> void {
            if ((int)cur.size() == 2 * n) {
                res.push_back(cur);
                return;
            }
            if (open_c < n) {
                cur.push_back('(');
                self(self, open_c + 1, close_c);
                cur.pop_back();
            }
            if (close_c < open_c) {
                cur.push_back(')');
                self(self, open_c, close_c + 1);
                cur.pop_back();
            }
        };
        dfs(dfs, 0, 0);
        return res;
    }
};

class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> res = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        dfs(0, 0, n, sb, res);
        return res;
    }
    private void dfs(int open, int close, int n, StringBuilder sb, List<String> res) {
        if (sb.length() == 2 * n) {
            res.add(sb.toString());
            return;
        }
        if (open < n) {
            sb.append('(');
            dfs(open + 1, close, n, sb, res);
            sb.deleteCharAt(sb.length() - 1);
        }
        if (close < open) {
            sb.append(')');
            dfs(open, close + 1, n, sb, res);
            sb.deleteCharAt(sb.length() - 1);
        }
    }
}

var generateParenthesis = function(n) {
    const res = [];
    function backtrack(openC, closeC, path) {
        if (path.length === 2 * n) {
            res.push(path.join(''));
            return;
        }
        if (openC < n) {
            path.push('(');
            backtrack(openC + 1, closeC, path);
            path.pop();
        }
        if (closeC < openC) {
            path.push(')');
            backtrack(openC, closeC + 1, path);
            path.pop();
        }
    }
    backtrack(0, 0, []);
    return res;
};
